return [
  {
    json: {
      _smokeTest: true,
      title: 'Q3 Planning',
      start: '2026-08-03T10:00:00+02:00',
      end: '2026-08-03T11:00:00+02:00',
      attendees: ['Alice', 'Bob'],
      location: 'Zoom',
      agenda: '1. Goals\n2. Risks',
      notes: 'Optional freeform notes',
      folder: '/Work/Meetings',
    },
  },
];

const FOLDER_RE = /^(\/[A-Za-z0-9._-]+)+$/;
const DEFAULT_FOLDER = '/Work/Meetings';

const item = $input.first().json;
const body =
  item.body && typeof item.body === 'object' && !Array.isArray(item.body)
    ? item.body
    : item;

const smokeTest = Boolean(body._smokeTest);
const title = String(body.title ?? '').trim();
if (!title) {
  throw new Error('Missing required field: title');
}

let attendees = [];
if (Array.isArray(body.attendees)) {
  attendees = body.attendees.map((a) => String(a).trim()).filter(Boolean);
} else if (typeof body.attendees === 'string' && body.attendees.trim()) {
  attendees = body.attendees
    .split(',')
    .map((a) => a.trim())
    .filter(Boolean);
}

const folderRaw = String(body.folder ?? DEFAULT_FOLDER).trim().replace(/\/$/, '') || DEFAULT_FOLDER;
if (!FOLDER_RE.test(folderRaw)) {
  throw new Error(`Invalid folder "${folderRaw}". Expected /Work/Meetings`);
}

return [
  {
    json: {
      title,
      start: String(body.start ?? '').trim(),
      end: String(body.end ?? '').trim(),
      attendees,
      location: String(body.location ?? '').trim(),
      agenda: String(body.agenda ?? '').trim(),
      notes: String(body.notes ?? '').trim(),
      folder: folderRaw,
      viaWebhook: !smokeTest,
    },
  },
];

const BUILDER = 'http://notebook-builder:8080';
const meeting = $input.first().json;

const body = {
  title: String(meeting.title || '').trim(),
  start: String(meeting.start || '').trim(),
  end: String(meeting.end || '').trim(),
  location: String(meeting.location || '').trim(),
  attendees: Array.isArray(meeting.attendees) ? meeting.attendees : [],
  agenda: String(meeting.agenda || ''),
  notes: String(meeting.notes || ''),
  template: 'Blank',
};

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: `${BUILDER}/v1/meeting-rmdoc`,
  headers: { 'Content-Type': 'application/json' },
  body,
  encoding: 'arraybuffer',
  returnFullResponse: true,
  timeout: 60000,
});

const status = response.statusCode || response.status || 0;
if (status < 200 || status >= 300) {
  const detail = Buffer.isBuffer(response.body)
    ? response.body.toString('utf8')
    : String(response.body ?? '');
  throw new Error(`notebook-builder failed (status=${status}): ${detail.slice(0, 500)}`);
}

function asBuffer(payload) {
  if (Buffer.isBuffer(payload)) return payload;
  if (payload?.type === 'Buffer' && Array.isArray(payload.data)) {
    return Buffer.from(payload.data);
  }
  if (payload instanceof ArrayBuffer) return Buffer.from(payload);
  if (ArrayBuffer.isView(payload)) {
    return Buffer.from(payload.buffer, payload.byteOffset, payload.byteLength);
  }
  if (typeof payload === 'string') return Buffer.from(payload, 'binary');
  throw new Error(`Unexpected rmdoc payload type: ${typeof payload}`);
}

const rmdoc = asBuffer(response.body);
if (rmdoc.length < 100) {
  throw new Error(`notebook-builder returned empty rmdoc (${rmdoc.length} bytes)`);
}

const headers = response.headers || {};
const filename =
  String(headers['x-filename'] || headers['X-Filename'] || '').trim() ||
  `${body.title.replace(/[^A-Za-z0-9._-]+/g, '-') || 'Meeting'}.rmdoc`;

const binary = await this.helpers.prepareBinaryData(rmdoc, filename, 'application/zip');

return [
  {
    json: {
      title: body.title,
      filename,
      folder: String(meeting.folder || '/Work/Meetings'),
      viaWebhook: Boolean(meeting.viaWebhook),
    },
    binary: { data: binary },
  },
];
